import '../models/models.dart';
import '../core/app_constants.dart';

int _c = 0;
String _id(String prefix) => '$prefix-${_c++}';

List<ContentItem> _items(String prefix, List<Map<String, dynamic>> rows) {
  return rows.map((r) => ContentItem(id: _id(prefix), fields: r)).toList();
}

